interface Message { role: 'user' | 'assistant'; content: string; tokens: number; }

interface Turn { user: Message; assistant?: Message; }  // 按轮组织便于摘要

class ContextManager {
  private turns: Turn[] = [];
  private summary: string | null = null;

  constructor(
    private systemPrompt: string,
    private budgetTokens: number,
    private recentTurns: number,
    private summarize: (text: string) => Promise<string>,  // 注入 LLM
  ) {}

  async buildContext(): Promise<Array<{ role: string; content: string }>> {
    const system = [{ role: 'system', content: this.systemPrompt }];
    const sysTokens = this.approxTokens(this.systemPrompt);
    const recent = this.turns.slice(-this.recentTurns);
    let older = this.turns.slice(0, -this.recentTurns);

    let total = sysTokens + this.turnTokens(recent) + (this.summary ? this.approxTokens(this.summary) : 0);

    // 预算仍不够时：从最旧开始把更多轮次并入摘要区
    while (total > this.budgetTokens && this.turns.length > 0 && older.length < this.turns.length - 1) {
      older.push(this.turns[this.turns.length - older.length - 2]);
      total = sysTokens + this.turnTokens(recent) + this.turnTokens(older) + (this.summary ? this.approxTokens(this.summary) : 0);
    }

    if (older.length > 0) {
      const raw = older.map((t) => `User: ${t.user.content}\\nAssistant: ${t.assistant?.content ?? ''}`).join('\\n\\n');
      this.summary = [this.summary, await this.summarize(raw)].filter(Boolean).join('\\n');  // 增量合并旧摘要
    }

    const msgs: Array<{ role: string; content: string }> = [...system];
    if (this.summary) msgs.push({ role: 'system', content: `此前对话摘要：${this.summary}` });
    for (const t of recent) {
      msgs.push({ role: 'user', content: t.user.content });
      if (t.assistant) msgs.push({ role: 'assistant', content: t.assistant.content });
    }
    return msgs;
  }

  private turnTokens(turns: Turn[]): number {
    return turns.reduce((s, t) => s + t.user.tokens + (t.assistant?.tokens ?? 0), 0);
  }
  private approxTokens(s: string): number { return Math.ceil(s.length / 4); }
}

设计要点：system 永远保留且不参与压缩；摘要增量合并（旧摘要+新入档内容一起总结）避免信息反复丢失；summarize 作为注入函数便于 mock 测试；生产版应记录“被压缩”标记保证可观测，并对摘要丢失的关键事实（如用户偏好）走显式 memory 而非指望摘要保留。
